from typing import Callable, Optional, Sequence, Tuple, TypeVar, Hashable
State = TypeVar("State", bound=Hashable)
Block = TypeVar("Block", bound=Hashable)

def merkle_damgard(f, iv, msg):
    state = iv
    for block in msg:
        state = f(state, block)
    return state

def md_collision_to_compress(f, iv, m1, m2):
    """Theorem 5.2: turn an equal-length full-hash collision into a
    compression-function collision (p1 != p2 with f(*p1) == f(*p2))."""
    if len(m1) != len(m2) or list(m1) == list(m2):
        return None
    if merkle_damgard(f, iv, m1) != merkle_damgard(f, iv, m2):
        return None
    s1, s2 = iv, iv
    for b1, b2 in zip(m1, m2):
        p1, p2 = (s1, b1), (s2, b2)
        if p1 != p2 and f(*p1) == f(*p2):
            return (p1, p2)
        s1, s2 = f(s1, b1), f(s2, b2)
    return None

if __name__ == "__main__":
    f = lambda s, b: (s + b) % 257
    print(md_collision_to_compress(f, 0, [1, 256], [256, 1]))

def merkle_damgard(f, iv, msg):
