def foldl_convergence(f, a1, a2, msg):
    """Theorem 6.1: from two distinct start states that converge under the same
    message, extract the first compression step (s1, s2, b) with s1 != s2 and
    f(s1, b) == f(s2, b)."""
    if a1 == a2 or merkle_damgard(f, a1, msg) != merkle_damgard(f, a2, msg):
        return None
    s1, s2 = a1, a2
    for b in msg:
        if f(s1, b) == f(s2, b):
            return (s1, s2, b)
        s1, s2 = f(s1, b), f(s2, b)
    return None

if __name__ == "__main__":
    f = lambda s, b: (s + b) % 257
    print(foldl_convergence(f, 0, 257, [3, 7, 2]))

def merkle_damgard(f, iv, msg):
    state = iv
    for block in msg:
        state = f(state, block)
    return state

def length_extension(f, known_digest, suffix):
    """Theorem 7.1: compute H(m1 ++ suffix) from h = H(m1) alone."""
    return merkle_damgard(f, known_digest, suffix)

if __name__ == "__main__":
    f = lambda s, b: 2 * s + b
    iv, secret, suffix = 9, [1, 1, 0, 1], [0, 1, 1]
    h = merkle_damgard(f, iv, secret)
    forged = length_extension(f, h, suffix)
    genuine = merkle_damgard(f, iv, secret + suffix)
    print("forgery matches:", forged == genuine)

